"""words.json -> src/videos/frost/words.ts (the only timing input of story.ts). usage: python words_to_ts.py words.json out.ts"""
import json, sys
w = json.load(open(sys.argv[1]))
rows = ",\n".join(f'  ["{x["w"]}", {x["s"]:.3f}, {x["e"]:.3f}]' for x in w)
open(sys.argv[2], "w").write(
    "// GENERATED by stories/frost/voice/words_to_ts.py from words.json: [word, start s, end s]. Do not edit by hand.\n"
    f"export const WORDS: [string, number, number][] = [\n{rows},\n];\n")
print(len(w), "words ->", sys.argv[2])
